   328    bool sanitize (hb_sanitize_context_t *c) const
   329    {
   330      TRACE_SANITIZE (this);
   331      return_trace (likely (c->check_struct (this) &&
   332                            version >= 1 &&
   333                            strikes.sanitize (c, this)));
   334    }
   335
   336    bool add_strike (hb_subset_context_t *c,
   337                     const void *dst_base,
   338                     unsigned int i,
   339                     unsigned int sbix_len) const {
   340      if (strikes[i].is_null () ||
   341          sbix_len < (unsigned int) strikes[i])
   342        return false;
   343
   344      return (this+strikes[i]).subset (c, sbix_len - (unsigned int) strikes[i]);
   345    }
   346
   347    bool serialize_strike_offsets (hb_subset_context_t *c,
   348                                   const void *dst_base,
   349                                   unsigned int sbix_len) const
   350    {
   351      TRACE_SERIALIZE (this);
   352
   353      auto *out = c->serializer->start_embed<LOffsetLArrayOf<SBIXStrike>> ();
   354      if (unlikely (!out)) return_trace (false);
   355      if (unlikely (!c->serializer->extend_min(out))) return_trace (false);
   356
   357      hb_vector_t<LOffsetTo<SBIXStrike>*> new_strikes;
   358      hb_vector_t<hb_serialize_context_t::objidx_t> objidxs;
   359      for (int i = strikes.len - 1; i >= 0; --i)
   360      {
   361        auto* o = out->serialize_append (c->serializer);
   362        if (unlikely (!o)) return_trace (false);
   363        *o = 0;
   364        auto snap = c->serializer->snapshot ();
   365        c->serializer->push ();
   366        bool ret = add_strike(c, dst_base, i, sbix_len);
   367        if (!ret)
   368        {
   369          c->serializer->pop_discard ();
   370          out->pop();
   371          c->serializer->revert (snap);
   372        }
   373        else
   374        {
   375          objidxs.push (c->serializer->pop_pack ());
   376          new_strikes.push (o);
   377        }
   378      }
   379      for (unsigned int i = 0; i < new_strikes.length; ++i)
   380        c->serializer->add_link (*new_strikes[i], objidxs[new_strikes.length - 1 - i], dst_base);
   381
   382      return_trace (true);
   383    }
   384
   385    bool subset (hb_subset_context_t* c) const
   386    {
   387      TRACE_SUBSET (this);
   388
   389      sbix *sbix_prime = c->serializer->start_embed<sbix> ();
   390      if (unlikely (!sbix_prime)) return_trace (false);
   391      if (unlikely (!c->serializer->embed (this->version))) return_trace (false);
   392      if (unlikely (!c->serializer->embed (this->flags))) return_trace (false);
   393      hb_blob_ptr_t<sbix> table = hb_sanitize_context_t().reference_table<sbix> (c->plan->source);
   394      const unsigned int sbix_len = table.get_blob ()->length;
   395      table.destroy ();
   396
   397      return_trace (serialize_strike_offsets (c, sbix_prime, sbix_len));
   398    }
