   401    HBUINT16      version;        /* Table version number — set to 1 */
   402    HBUINT16      flags;          /* Bit 0: Set to 1. Bit 1: Draw outlines.
   403                                   * Bits 2 to 15: reserved (set to 0). */
   404    LOffsetLArrayOf<SBIXStrike>
   405                  strikes;        /* Offsets from the beginning of the 'sbix'
   406                                   * table to data for each individual bitmap strike. */
   407    public:
   408    DEFINE_SIZE_ARRAY (8, strikes);
